previewCss:
.darma-loader-lighthouse-beam {
  position: relative;
  width: 52px;
  height: 52px;
}
.darma-loader-lighthouse-beam::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 20px;
  height: 32px;
  margin-left: -10px;
  background: var(--loader-color, #6366f1);
  clip-path: polygon(25% 0, 75% 0, 100% 100%, 0 100%);
  z-index: 2;
}
.darma-loader-lighthouse-beam::after {
  content: "";
  position: absolute;
  top: 12px;
  left: 50%;
  width: 14px;
  height: 10px;
  margin-left: -7px;
  border-radius: 2px;
  background: #4338ca;
  z-index: 3;
}
.darma-loader-lighthouse-beam i {
  position: absolute;
  top: 17px;
  left: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  border-radius: 50%;
  background: conic-gradient(from -12deg, color-mix(in srgb, var(--loader-color, #6366f1) 55%, transparent) 0 24deg, transparent 24deg 360deg);
  z-index: 1;
  animation: darma-loader-lighthouse-beam-spin 2.4s linear infinite;
}
@keyframes darma-loader-lighthouse-beam-spin { to { transform: rotate(360deg); } }

